create or replace function pg_temp.rs(t text) returns int language sql as $$ select (replace((regexp_match(t, '₹\s?([\d,]+)'))[1], ',', ''))::int * 100 $$;
create or replace function pg_temp.bank(t text) returns jsonb language sql as $$ select case when t is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('text', t, 'bank', (regexp_match(t, '(Flipkart Axis|Amazon Pay ICICI|SBI|HDFC|ICICI|Axis|Kotak|IDFC|RBL)'))[1], 'discountPercent', (regexp_match(t, '(\d+)%'))[1]::int, 'maxDiscount', case when t ~ 'up to' then pg_temp.rs(split_part(t, 'up to', 2)) end, 'flatDiscount', case when t !~ '%' then pg_temp.rs(t) end)) end $$;
create or replace function pg_temp.coupon(t text) returns jsonb language sql as $$ select case when t is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('code', case when t ~ ':' then trim(split_part(t, ':', 1)) end, 'text', t, 'flatDiscount', pg_temp.rs(t), 'percent', (regexp_match(t, '(\d+)%'))[1]::int)) end $$;
create or replace function pg_temp.voucher(t text) returns jsonb language sql as $$ select case when t is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('text', t, 'value', pg_temp.rs(t))) end $$;

