$json$::jsonb) e),
p as (
  insert into public.products (id,slug,name,brand,category,subcategory,subtitle,description,base_price_amount,mrp_amount,theme_color,rating,review_count,tags,stats)
  select e->>0, e->>0, e->>1, e->>2, e->>3, e->>4, (e->>2)||' '||(e->>4), e->>5, (e->>6)::int*100, (e->>7)::int*100,
    case e->>3 when 'electronics' then '#5b7cfa' when 'clothing' then '#d9a15e' else '#e07a9b' end,
    (e->>8)::numeric, (e->>9)::int, array(select jsonb_array_elements_text(e->10)),
    jsonb_build_array(jsonb_build_object('label','MRP','value','₹'||to_char((e->>7)::int,'FM99,99,999')))
  from src returning id),
v as (
  insert into public.product_variants (id,product_id,name,sku) select (e->>0)||'-std', e->>0, 'Standard', upper(e->>0) from src returning id),
ours as (
  insert into public.offers (id,product_id,variant_id,retailer_id,price_amount,mrp_amount,rating,review_count,delivery_label,delivery_days,delivery_price_amount,stock,returns_days,bank_offers,coupons,vouchers)
  select 'offer_semil_'||(e->>0), e->>0, (e->>0)||'-std', 'semil', (e->>6)::int*100, (e->>7)::int*100, (e->>8)::numeric, (e->>9)::int,
    'In 2 days', 2, 0, 'in_stock', case when e->>3='beauty' then 7 else 10 end,
    pg_temp.bank(e->11->>'bankOffer'), pg_temp.coupon(e->11->>'coupon'), pg_temp.voucher(e->11->>'voucher')
  from src returning id)
insert into public.offers (id,product_id,variant_id,retailer_id,price_amount,mrp_amount,rating,review_count,delivery_label,delivery_days,delivery_price_amount,stock,returns_days,bank_offers,coupons,vouchers)
select 'offer_'||r||'_'||(e->>0), e->>0, (e->>0)||'-std', r, (x->>1)::int*100, (e->>7)::int*100, nullif(x->>2,'')::numeric, 0,
  case r when 'amazon' then 'Tomorrow' else 'In 3 days' end, case r when 'amazon' then 1 else 3 end,
  case when (x->>1)::int < 500 then 4000 else 0 end, 'in_stock', case r when 'amazon' then 10 else 7 end,
  pg_temp.bank(x->>3), pg_temp.coupon(x->>4), pg_temp.voucher(x->>5)
from src, jsonb_array_elements(e->12) x, lateral (select case x->>0 when 'A' then 'amazon' else 'flipkart' end as r) rr;

select (select count(*) from public.products) products, (select count(*) from public.offers) offers;
